def solve():
    from collections import deque

    n, k = map(int, input().split())
    s = list(input())

    def convert(c):
        return 'A' if c == 'B' else 'B'

    b_count = s.count('B')
    diff = abs(b_count - k)

    ans = deque()
    i, c = 1, ''

    if b_count > k:
        while len(ans) < diff:
            if s[i-1] == 'B':
                i += 1
            else:
                ans.append((i, convert(s[i-1])))
                for j in range(i, n+1):
                    ans.append((j, convert('A')))
                break 

    elif b_count < k:    
        while len(ans) < diff:
            if s[-i] == 'A':
                i += 1
            else:
                c = 'B'
                for j in range(i-1, n+1):
                    ans.append((j, convert(c)))
                break

    count = len(list(ans))
    print(count)
    for res in list(ans):
        print(*res)

